/// @title System Wallet
/// @notice Upgradeable system wallet supporting ETH & multiple ERC20 tokens
/// @author nugi
contract System_wallet is
    MainAccesControlPipes,
    UUPSUpgradeable,
    PausableUpgradeable,
    SystemReentrancyGuard,
    AddressUtils
{
    using SafeERC20 for IERC20;

    /* =======================
